#include <bits/stdc++.h>
using namespace std;
int main(){set<int> need{611,615,617,619,623,625,635,647,655};unsigned c;long attempts=0;while(cin>>c){unsigned a[9]={};int k=0;for(int i=0;i<8;i++)for(int j=i+1;j<8;j++,k++)if(c>>k&1)a[i]|=1<<j;else a[j]|=1<<i;for(unsigned p=0;p<256;p++){unsigned b[9];copy(a,a+9,b);b[8]=p;for(int i=0;i<8;i++)if(!(p>>i&1))b[i]|=256;int dp[512][9]={};for(int i=0;i<9;i++)dp[1<<i][i]=1;for(int s=1;s<512;s++)for(int i=0;i<9;i++)if(dp[s][i]){unsigned z=b[i]&~s;while(z){int v=__builtin_ctz(z);z&=z-1;dp[s|1<<v][v]+=dp[s][i];}}int h=accumulate(dp[511],dp[511]+9,0);attempts++;if(need.erase(h)){unsigned long long code=0;int k=0;for(int i=0;i<9;i++)for(int j=i+1;j<9;j++,k++)if(b[i]>>j&1)code|=1ull<<k;cout<<h<<" "<<code<<" "<<c<<" "<<p<<endl;}if(need.empty()){cerr<<"all nine filled in "<<attempts<<" extensions\n";return 0;}}}cerr<<"missing "<<need.size()<<"\n";return 1;}
